// La anti-repetición (misma alerta en 10 min) la hace Enviar_Alerta consultando alertas_auditoria.
// (En N8N 2.x la memoria del flujo no se conserva entre ejecuciones de flujos publicados.)
function primeraVez() { return true; }

// R4: más de 5 autenticaciones fallidas en 10 minutos.
// Fuente 1: log de PostgreSQL (siempre). Fuente 2: auth.log vía Loki (si M5 ya lo dejó listo;
// si Loki no existe, el nodo anterior falla en silencio y se usa solo el log de PG).
const UMBRAL = 5;
const pgRow = $('Consultar PostgreSQL').first().json;
const desde = pgRow.desde || '';
const lineas = String(pgRow.contenido || '').split('\n');
const fallosPG = lineas.filter(l =>
  l.includes('password authentication failed') && l.slice(0, 19) >= desde);
const usuarios = [...new Set(fallosPG.map(l => (l.match(/for user "([^"]+)"/) || [])[1]).filter(Boolean))];

let fallosSSH = 0;
try {
  const v = $input.first().json?.data?.result?.[0]?.value?.[1];
  fallosSSH = Number(v) || 0;
} catch (e) { fallosSSH = 0; }

const total = fallosPG.length + fallosSSH;
if (total <= UMBRAL) return [];
if (!primeraVez('R4')) return [];
return [{ json: {
  codigo: 'R4',
  severidad: 'CRÍTICA',
  tipo: 'Múltiples autenticaciones fallidas (posible fuerza bruta)',
  tabla: 'N/A (logs de PostgreSQL / auth.log)',
  detalle: `Intentos fallidos en 10 min: ${total} (PostgreSQL: ${fallosPG.length}, SSH: ${fallosSSH}; umbral: ${UMBRAL})`,
  query: 'pg_read_file(log) + Loki {job="auth"} |= "Failed password"',
  usuario: usuarios.join(', ') || (fallosSSH ? 'SSH' : 'desconocido'),
  accion: 'Identificar la IP de origen y bloquearla (ufw deny from <ip>). Revisar si la cuenta fue comprometida.'
}}];
